# 사용자 제공 2019~2025 기출은 '답안 암기은행'이 아니라 출제영역/소진지도에 사용한다.
qs=data.get('writtenQuestions',[])

def count_theme(patterns):
    c=0
    for q in qs:
        s=q.get('question','')
        if any(re.search(p,s,re.I) for p in patterns): c+=1
    return c

